package com.mag.anyauto;

import android.content.ComponentName;
import android.content.Context;
import android.content.Intent;
import android.content.pm.ApplicationInfo;
import android.content.pm.PackageManager;
import android.graphics.drawable.Drawable;
import android.util.Log;

import org.json.JSONObject;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;

/**
 * Configuration for dedicated single-app launcher mode generated by AAMaKer.
 */
public final class TargetAppConfig {
    private static final String TAG = "AnyAuto.Target";
    private static final String ASSET_FILE = "anyauto_target.json";

    public static final class Info {
        public final ComponentName component;
        public final String appName;
        public final String packageName;
        public final String activityName;

        public Info(ComponentName component, String appName, String packageName, String activityName) {
            this.component = component;
            this.appName = appName;
            this.packageName = packageName;
            this.activityName = activityName;
        }

        public Drawable loadIcon(Context context) {
            try {
                return context.getPackageManager().getApplicationIcon(packageName);
            } catch (Throwable t) {
                return null;
            }
        }
    }

    private static Info cachedInfo;
    private static boolean resolved = false;

    public static synchronized Info get(Context context) {
        if (resolved) return cachedInfo;
        resolved = true;
        Context appCtx = context.getApplicationContext();

        // 1. Try reading from assets/anyauto_target.json
        try (InputStream is = appCtx.getAssets().open(ASSET_FILE)) {
            byte[] bytes = new byte[is.available()];
            int read = is.read(bytes);
            if (read > 0) {
                JSONObject json = new JSONObject(new String(bytes, 0, read, StandardCharsets.UTF_8));
                String pkg = json.optString("targetPackage", "").trim();
                String act = json.optString("targetActivity", "").trim();
                String name = json.optString("appName", "").trim();
                if (!pkg.isEmpty()) {
                    ComponentName comp = resolveComponent(appCtx, pkg, act);
                    if (comp != null) {
                        cachedInfo = new Info(comp, name.isEmpty() ? pkg : name, pkg, act);
                        Prefs.setLast(appCtx, comp);
                        Prefs.setCarApp(appCtx, comp, true);
                        Log.i(TAG, "Dedicated target app from assets: " + comp.flattenToShortString());
                        return cachedInfo;
                    }
                }
            }
        } catch (Throwable ignored) {
        }

        // 2. Try reading from AndroidManifest meta-data
        try {
            ApplicationInfo ai = appCtx.getPackageManager().getApplicationInfo(
                    appCtx.getPackageName(), PackageManager.GET_META_DATA);
            if (ai != null && ai.metaData != null) {
                String pkg = ai.metaData.getString("com.aamaker.anyauto.TARGET_PACKAGE");
                String act = ai.metaData.getString("com.aamaker.anyauto.TARGET_ACTIVITY");
                if (pkg != null && !pkg.trim().isEmpty()) {
                    ComponentName comp = resolveComponent(appCtx, pkg.trim(), act != null ? act.trim() : null);
                    if (comp != null) {
                        String name = ai.loadLabel(appCtx.getPackageManager()).toString();
                        cachedInfo = new Info(comp, name, pkg.trim(), act);
                        Prefs.setLast(appCtx, comp);
                        Prefs.setCarApp(appCtx, comp, true);
                        Log.i(TAG, "Dedicated target app from manifest: " + comp.flattenToShortString());
                        return cachedInfo;
                    }
                }
            }
        } catch (Throwable ignored) {
        }

        return null;
    }

    public static boolean isDedicated(Context context) {
        return get(context) != null;
    }

    private static ComponentName resolveComponent(Context ctx, String pkg, String act) {
        if (act != null && !act.isEmpty()) {
            return new ComponentName(pkg, act);
        }
        Intent launch = ctx.getPackageManager().getLaunchIntentForPackage(pkg);
        if (launch != null && launch.getComponent() != null) {
            return launch.getComponent();
        }
        return new ComponentName(pkg, "");
    }
}
